import React from 'react';
import './CourseItem.css';

const CourseItem = ({ title, desc }) => {
  return (
    <div className="courseItem">
      <span class="tooltip" data-tooltip={desc.split('\n').map((line, i) => (
            <div key={i}>{line}</div>
          ))}>
        {title} 
      </span>
    </div>
  );
};

export default CourseItem;
